-- Plan 12: the first two levels are quicker (xp to next level 24 and 50, i.e. 12 wolves and 25 wolves; then 900, 2200, 4400).
-- Avatars are recalculated from the xp they hold on the plan 10 ladder (200, 400, 900, 2200, 4400): total xp is kept,
-- the level is worked out again, max health follows, hp is clamped, coins, gear and place are untouched, dead stays dead.
UPDATE characters SET
  xp = CASE WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 7574 THEN 0 ELSE (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) - (CASE WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 7574 THEN 7574 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 3174 THEN 3174 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 974 THEN 974 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 74 THEN 74 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 24 THEN 24 ELSE 0 END) END,
  level = (CASE WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 7574 THEN 6 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 3174 THEN 5 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 974 THEN 4 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 74 THEN 3 WHEN (CASE level WHEN 1 THEN 0 WHEN 2 THEN 200 WHEN 3 THEN 600 WHEN 4 THEN 1500 WHEN 5 THEN 3700 WHEN 6 THEN 8100 END + xp) >= 24 THEN 2 ELSE 1 END);

UPDATE characters SET
  max_hp = (CASE level WHEN 1 THEN 70 WHEN 2 THEN 80 WHEN 3 THEN 92 WHEN 4 THEN 106 WHEN 5 THEN 122 WHEN 6 THEN 140 END) + (CASE armor WHEN 'leather' THEN 12 WHEN 'chain' THEN 24 WHEN 'plate' THEN 40 ELSE 0 END),
  hp = MIN(hp, (CASE level WHEN 1 THEN 70 WHEN 2 THEN 80 WHEN 3 THEN 92 WHEN 4 THEN 106 WHEN 5 THEN 122 WHEN 6 THEN 140 END) + (CASE armor WHEN 'leather' THEN 12 WHEN 'chain' THEN 24 WHEN 'plate' THEN 40 ELSE 0 END));
